   713  // Convert the imported data to the internal verbose representation
   714  void ASEImporter::BuildUniqueRepresentation(ASE::Mesh &mesh) {
   715      // allocate output storage
   716      std::vector<aiVector3D> mPositions;
   717      std::vector<aiVector3D> amTexCoords[AI_MAX_NUMBER_OF_TEXTURECOORDS];
   718      std::vector<aiColor4D> mVertexColors;
   719      std::vector<aiVector3D> mNormals;
   720      std::vector<BoneVertex> mBoneVertices;
   721
   722      unsigned int iSize = (unsigned int)mesh.mFaces.size() * 3;
   723      mPositions.resize(iSize);
   724
   725      // optional texture coordinates
   726      for (unsigned int i = 0; i < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++i) {
   727          if (!mesh.amTexCoords[i].empty()) {
   728              amTexCoords[i].resize(iSize);
   729          }
   730      }
   731      // optional vertex colors
   732      if (!mesh.mVertexColors.empty()) {
   733          mVertexColors.resize(iSize);
   734      }
   735
   736      // optional vertex normals (vertex normals can simply be copied)
   737      if (!mesh.mNormals.empty()) {
   738          mNormals.resize(iSize);
   739      }
   740      // bone vertices. There is no need to change the bone list
   741      if (!mesh.mBoneVertices.empty()) {
   742          mBoneVertices.resize(iSize);
   743      }
   744
   745      // iterate through all faces in the mesh
   746      unsigned int iCurrent = 0, fi = 0;
   747      for (std::vector<ASE::Face>::iterator i = mesh.mFaces.begin(); i != mesh.mFaces.end(); ++i, ++fi) {
   748          for (unsigned int n = 0; n < 3; ++n, ++iCurrent) {
   749              mPositions[iCurrent] = mesh.mPositions[(*i).mIndices[n]];
   750
   751              // add texture coordinates
   752              for (unsigned int c = 0; c < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++c) {
   753                  if (mesh.amTexCoords[c].empty()) break;
   754                  amTexCoords[c][iCurrent] = mesh.amTexCoords[c][(*i).amUVIndices[c][n]];
   755              }
   756              // add vertex colors
   757              if (!mesh.mVertexColors.empty()) {
   758                  mVertexColors[iCurrent] = mesh.mVertexColors[(*i).mColorIndices[n]];
   759              }
   760              // add normal vectors
   761              if (!mesh.mNormals.empty()) {
   762                  mNormals[iCurrent] = mesh.mNormals[fi * 3 + n];
   763                  mNormals[iCurrent].Normalize();
   764              }
   765
   766              // handle bone vertices
   767              if ((*i).mIndices[n] < mesh.mBoneVertices.size()) {
   768                  // (sometimes this will cause bone verts to be duplicated
   769                  //  however, I' quite sure Schrompf' JoinVerticesStep
   770                  //  will fix that again ...)
   771                  mBoneVertices[iCurrent] = mesh.mBoneVertices[(*i).mIndices[n]];
   772              }
   773              (*i).mIndices[n] = iCurrent;
   774          }
   775      }
   776
   777      // replace the old arrays
   778      mesh.mNormals = mNormals;
   779      mesh.mPositions = mPositions;
   780      mesh.mVertexColors = mVertexColors;
